#ifndef EDC_BUNDLED_MODELS_CATALOG_H
#define EDC_BUNDLED_MODELS_CATALOG_H

#include <stddef.h>

/*
 * The AI-model catalog (models_catalog.json, generated by tools/gen_models.py) is
 * embedded into the binary at build time by //tools:embed_blob.py, so the first-run
 * wizard and the model picker work offline, with no file next to the executable.
 *
 * edc_models.c reads these bytes (the embedded copy is the default; the env var
 * EDGECLAW_MODELS_CATALOG can point at a file for dev/tests).
 */

extern const unsigned char edc_bundled_models_catalog[];
extern const size_t edc_bundled_models_catalog_size;

#endif /* EDC_BUNDLED_MODELS_CATALOG_H */
